Lemma rdn_mrd : forall segs bs m (a : Z),
  BPropExec.rdn segs m (Z_to_bv 64 a) (length bs) = Some bs -> 0 <= a -> a + Z.of_nat (length bs) <= 2 ^ 64 ->
