  Ltac csz := cbn [cells_size csize cells_bytes cbytes length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ Pos.add app repeat map] in *.

  Definition cellsZ (cs : list cell) : list Z := map bv_unsigned (cells_bytes cs).
