  Lemma segment_byte_at_zero1 : forall s (base n : N) (off : N),
    zscanN s 64 base n = true -> (base + n <= Z.to_N (Uint63.to_Z (PrimString.length s) / 2))%N -> (base <= off < base + n)%N ->
